import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0051: Typed memory relationship direction","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0051-typed-memory-relationship-direction.md","filePath":"adrs/0051-typed-memory-relationship-direction.md","lastUpdated":1789092097000}`),u={name:`adrs/0051-typed-memory-relationship-direction.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[9]||=a(`<h1 id="adr-0051-typed-memory-relationship-direction" tabindex="-1">ADR-0051: Typed memory relationship direction <a class="header-anchor" href="#adr-0051-typed-memory-relationship-direction" aria-label="Permalink to “ADR-0051: Typed memory relationship direction”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-09-06 · Refines <a href="/adrs/0048-spatial-memory-and-knowledge-graph">ADR-0048</a> and <a href="/adrs/0050-map-zoom-and-connector-motion">ADR-0050</a></p><h2 id="context-and-evidence" tabindex="-1">Context and evidence <a class="header-anchor" href="#context-and-evidence" aria-label="Permalink to “Context and evidence”">​</a></h2>`,3),c(`p`,null,[l[1]||=i(`The decoder discarded `,-1),r(m,{term:`hindsight`},{default:n(()=>[...l[0]||=[i(`Hindsight`,-1)]]),_:1}),l[2]||=i(`'s `,-1),l[3]||=c(`code`,null,`linkType`,-1),l[4]||=i(`, merged different relationships on a pair, and animated every edge from serialized source to target. That ordering does not imply direction for associations. Hindsight's `,-1),l[5]||=c(`a`,{href:`https://hindsight.vectorize.io/developer/retain#building-connections`,target:`_blank`,rel:`noreferrer`},`retain documentation`,-1),l[6]||=i(` distinguishes meaning, entity and time-proximity connections from causal relationships. Its `,-1),l[7]||=c(`a`,{href:`https://hindsight.vectorize.io/blog/2026/04/16/constellation-view`,target:`_blank`,rel:`noreferrer`},`Constellation overview`,-1),l[8]||=i(` uses link-type colours. GOAT keeps its theme's node-type colours, as requested, while preserving relationship meaning.`,-1)]),l[10]||=a(`<p>Read-only inspection of the configured server on 2026-09-06 confirmed:</p><ul><li><code>engine/memory_engine.py:get_graph_data</code> derives entity pairs from shared entities and observation semantic pairs from shared source memories. The serialization order of these pairs is incidental.</li><li><code>engine/retain/link_utils.py:create_temporal_links_batch_per_fact</code> uses absolute time distance and creates reciprocal within-batch links. Temporal edges do not assert before/after ordering.</li><li><code>engine/causal_links.py</code> defines canonical <code>caused_by</code> plus legacy <code>causes</code>, <code>enables</code>, <code>prevents</code>. The writer stores the fact as source and its cause as target for <code>caused_by</code>.</li><li><code>engine/memories/pg/graph.py:graph_direct_links</code> preserves stored causal endpoints.</li><li>Knowledge links in GOAT come from saved <code>reflect_response.based_on</code> references.</li></ul><p>No remote code, bank configuration, or memory records were changed for this investigation.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Preserve a typed relationship on every edge. Canonicalize endpoint ordering only for symmetric associations, deduplicating reciprocal rows of the same type while retaining distinct types. Unknown server types remain unknown, never defaulting to a wiki link or causal relationship.</p><table tabindex="0"><thead><tr><th>Relationship</th><th>Motion</th><th>Highlighted connector colour</th></tr></thead><tbody><tr><td>Semantic, entity, temporal, co-occurrence</td><td>Both ways</td><td>Gradient between endpoint node colours</td></tr><tr><td>Caused by</td><td>Stored target (cause) to source (effect)</td><td>Cause node</td></tr><tr><td>Causes, enables, prevents</td><td>Stored source to target</td><td>Origin node</td></tr><tr><td>Wiki link or citation</td><td>Citing page to linked page or evidence</td><td>Citing node</td></tr><tr><td>Unknown</td><td>None</td><td>Muted</td></tr></tbody></table><p>Every dot retains its origin node&#39;s theme colour throughout travel. Hover takes temporary visual precedence over the pinned selection, which remains selected for Open. Its card overlays the canvas rather than taking layout height from it; selecting and clearing nodes cannot resize the projection or native hit-test surface. A fixed divider separates the legend. Compact node/type counts and solid/dashed line samples expose accurate tooltip and VoiceOver explanations, including preview counts and zero-type semantics. Active maps tint other connections softly; focused connections are stronger and unrelated connections recede. Direction illustrates the recorded relationship, not a live retrieval trace or network transmission.</p><p>An active map with no hovered or selected node stays still and creates no animation timeline. The animation preview keeps a maximum of 24 dots, deduplicates identical travel paths across relationship types, keeps association pairs together, and excludes missing endpoints. Existing activation, scene, Reduce Motion, and animation-setting gates remain. Layout ordering includes relationship type to remain deterministic after preserving multiple types on the same pair.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p>Regression tests cover reciprocal deduplication, distinct type retention, reversed caused-by motion, legacy direction, citation direction, unknown types, focus, missing endpoints and paired dot budgets. Multiple relationship types can share one curve and its tracers; these dots are not an exhaustive edge inspector. The Hindsight UI remains the full graph exploration destination.</p>`,10)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};